# 1. pass a value to another command (seed test behaviour)
@click.command()
@click.pass_context
def cli1(ctx):
    return ctx.invoke(other_cmd, 42)


@click.command()
@click.argument('arg', type=click.INT)
def other_cmd(arg):
    click.echo(arg)


show('invoke with value', runner.invoke(cli1, []))


# 2. invoke without values -> params get None
@click.command()
@click.pass_context
def cli2(ctx):
    return ctx.invoke(other_cmd)


show('invoke without value', runner.invoke(cli2, []))


# 3. command without callback handed to invoke
@click.command()
def no_callback():
    pass


@click.command()
@click.pass_context
def cli3(ctx):
    return ctx.invoke(no_callback)


show('invoke command without callback', runner.invoke(cli3, []))


# 4. forward reuses the values of the current command
@click.command()
@click.pass_context
@click.option('--count', default=1)
@click.option('--name', default='world')
@click.option('--expose/--no-expose', default=True)
@click.option('--hidden', default='x', expose_value=False)
@click.argument('arg', default='none')
def cli4(ctx, count, name, expose, hidden, arg):
    click.echo('%s %s %s %s' % (count, name, expose, arg))
    return ctx.forward(forwarded)


@click.command()
@click.option('--count', default=42)
@click.option('--name', default='default')
@click.option('--expose/--no-expose', default=False)
@click.option('--hidden', default='y', expose_value=False)
@click.argument('arg', default='none')
def forwarded(count, name, expose, hidden, arg):
    click.echo('%s %s %s %s' % (count, name, expose, arg))


show('forward defaults', runner.invoke(cli4, []))
show('forward with values',
     runner.invoke(cli4, ['--count=3', '--name=click', '--no-expose', 'x']))


# 5. explicit overrides win over forwarded defaults
@click.command()
@click.pass_context
@click.option('--n', default=1)
def cli5(ctx, n):
    click.echo('source n=%s' % n)
    return ctx.forward(forwarded5, n=23)


@click.command()
@click.option('--n', default=1)
def forwarded5(n):
    click.echo('target n=%s' % n)


show('forward with override', runner.invoke(cli5, ['--n=5']))


# 6. forwarding to a command without a callback / a plain function
