@click.pass_context
def cli6(ctx):
    return ctx.forward(no_callback)


@click.command()
@click.pass_context
def cli7(ctx):
    return ctx.forward(lambda: None)


show('forward command without callback', runner.invoke(cli6, []))
show('forward a plain function', runner.invoke(cli7, []))


