@click.command()
@click.pass_context
def cli8(ctx):
    return ctx.invoke(passthrough_cmd)


@click.command()
@click.pass_context
@click.option('--value', default='ctx')
def passthrough_cmd(ctx, value):
    click.echo('%s %s' % (ctx.info_name, value))


show('invoke pass_context command', runner.invoke(cli8, ['--value=x']))


@click.command()
@click.pass_context
def cli9(ctx):
    return ctx.forward(passthrough_cmd)


show('forward pass_context command', runner.invoke(cli9, []))


@click.command()
@click.pass_context
def cli10(ctx):
    ctx.invoke(passthrough_func, 1, foo='bar')


@click.pass_context
