def forward(*args, **kwargs):
        """Similar to :meth:`invoke` but fills in the default values of
        the parameters of the current command for those parameters of a
        new command which are not otherwise given.

        :param command: the command to forward to.  This needs to be an
                        instance of :class:`Command`.
        """
        self, cmd = args[:2]
        # Just kwargs, no positional arguments to deal with.
        if not isinstance(cmd, Command):
            raise TypeError('Callback is not a command.')
        for param in self.command.params:
            if param.name not in kwargs and param.expose_value:
                kwargs[param.name] = param.get_default(self)
        return self.invoke(cmd, **kwargs)

