import sys, io, contextlib, types
sys.path.insert(0, '/workspace')

# minimal stand-in for the docs clickdoctools ExampleRunner
import click
from click.helpers import echo

class Runner(object):
    def __init__(self):
        self.namespace = {'click': click, '__file__': 'dummy.py'}

    def declare(self, source):
        eval(compile(source, '<docs>', 'exec'), self.namespace)

    def run(self, source):
        buffer = []
        def invoke(cmd, args=None, prog_name=None, input=None):
            args = args or []
            prog_name = prog_name or (cmd.name or 'cli') + '.py'
            buffer.append(('$ %s %s' % (prog_name, ' '.join(args))).rstrip())
            old = sys.stdout
            sys.stdout = out = io.StringIO()
            try:
                try:
                    cmd.main(args=args, prog_name=prog_name)
                except SystemExit:
                    pass
            finally:
                sys.stdout = old
            buffer.extend(out.getvalue().splitlines())
        eval(compile(source, '<docs>', 'exec'), self.namespace, {'invoke': invoke, 'println': buffer.append})
        return buffer

